{"sql":"-- Data quality checks: NULL vectors, dimension mismatches, outliers per vector column
-- Create a temporary table to collect issues
DROP TABLE IF EXISTS tmp_vector_issues;
CREATE TEMP TABLE tmp_vector_issues(
  schema text,
  table_name text,
  column_name text,
  issue text,
  affected_rows bigint
);

WITH vec_cols AS (
  SELECT vac.schema, vac.table_name, vac.column_name, vac.dimensions, vac.data_type
  FROM vector_analysis_columns vac
)
INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
SELECT schema, table_name, column_name, 'NULL_vectors' AS issue,
       (SELECT count(*) FROM pg_catalog.format('%I.%I', schema, table_name)::regclass r, LATERAL (
          SELECT 1 FROM r WHERE (r)."" IS NULL
       ) s) AS affected_rows
FROM vec_cols
WHERE FALSE; -- placeholder, populating via dynamic SQL below

DO $$
DECLARE
  r RECORD;
  sql text;
  cnt_null bigint;
  cnt_mismatch bigint;
  cnt_nan bigint;
BEGIN
  FOR r IN SELECT schema, table_name, column_name, dimensions FROM vector_analysis_columns LOOP
    -- NULL vectors
    sql := format('SELECT count(*) FROM %I.%I WHERE %I IS NULL', r.schema, r.table_name, r.column_name);
    EXECUTE sql INTO cnt_null;

    IF cnt_null > 0 THEN
      INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
      VALUES (r.schema, r.table_name, r.column_name, 'NULL_vectors', cnt_null);
    END IF;

    -- Dimension mismatch: use vector_dims() for vector and halfvec
    BEGIN
      sql := format('SELECT count(*) FROM %I.%I WHERE %I IS NOT NULL AND vector_dims(%I) <> %s',
                    r.schema, r.table_name, r.column_name, r.column_name,
                    CASE WHEN r.dimensions IS NULL THEN 'vector_dims(' || quote_ident(r.column_name) || ')' ELSE r.dimensions::text END);
      EXECUTE sql INTO cnt_mismatch;

      IF cnt_mismatch > 0 THEN
        INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
        VALUES (r.schema, r.table_name, r.column_name, 'dimension_mismatch', cnt_mismatch);
      END IF;
    EXCEPTION WHEN undefined_function THEN
      -- For sparsevec or other types without vector_dims, skip
      NULL;
    END;

    -- NaN values within vectors: check string representation
    BEGIN
      sql := format('SELECT count(*) FROM %I.%I WHERE %I::text ~ ''NaN''', r.schema, r.table_name, r.column_name);
      EXECUTE sql INTO cnt_nan;
      IF cnt_nan > 0 THEN
        INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
        VALUES (r.schema, r.table_name, r.column_name, 'nan_values', cnt_nan);
      END IF;
    EXCEPTION WHEN others THEN
      NULL;
    END;
  END LOOP;
END $$;

-- Summarize issues
SELECT * FROM tmp_vector_issues ORDER BY affected_rows DESC NULLS LAST;"}

{"sql":"-- Rebuild data-quality issue collection with dynamic SQL only
DROP TABLE IF EXISTS tmp_vector_issues;
CREATE TEMP TABLE tmp_vector_issues(
  schema text,
  table_name text,
  column_name text,
  issue text,
  affected_rows bigint
);

-- Per-column statistics
DROP TABLE IF EXISTS tmp_vector_column_stats;
CREATE TEMP TABLE tmp_vector_column_stats(
  schema text,
  table_name text,
  column_name text,
  data_type text,
  typmod_dims integer,
  row_count bigint,
  null_count bigint,
  distinct_dims integer,
  min_dim integer,
  max_dim integer,
  avg_norm double precision,
  stddev_norm double precision,
  outliers_3sigma bigint
);

DO $$
DECLARE
  r RECORD;
  sql text;
  cnt_null bigint;
  cnt_inconsistent bigint;
  typdim integer;
  rc bigint;
  ddist integer;
  dmin integer;
  dmax integer;
  an double precision;
  sd double precision;
  out3 bigint;
  norm_expr text;
  dims_expr text;
BEGIN
  FOR r IN 
    SELECT schema, table_name, column_name, data_type, dimensions AS typmod_dims
    FROM vector_analysis_columns
  LOOP
    -- Row count
    sql := format('SELECT count(*) FROM %I.%I', r.schema, r.table_name);
    EXECUTE sql INTO rc;

    -- NULL count
    sql := format('SELECT count(*) FROM %I.%I WHERE %I IS NULL', r.schema, r.table_name, r.column_name);
    EXECUTE sql INTO cnt_null;

    -- Determine expressions per type
    IF r.data_type = 'vector' THEN
      norm_expr := format('vector_norm(%I)', r.column_name);
      dims_expr := format('vector_dims(%I)', r.column_name);
    ELSIF r.data_type = 'halfvec' THEN
      norm_expr := format('l2_norm(%I)', r.column_name);
      dims_expr := format('vector_dims(%I)', r.column_name);
    ELSIF r.data_type = 'sparsevec' THEN
      norm_expr := format('l2_norm(%I)', r.column_name);
      dims_expr := NULL; -- no dims fn
    ELSE
      norm_expr := NULL;
      dims_expr := NULL;
    END IF;

    -- Dimension consistency and stats when supported
    ddist := NULL; dmin := NULL; dmax := NULL; cnt_inconsistent := 0;
    IF dims_expr IS NOT NULL THEN
      -- distinct dims
      sql := format('SELECT count(DISTINCT %s) FROM %I.%I WHERE %I IS NOT NULL', dims_expr, r.schema, r.table_name, r.column_name);
      EXECUTE sql INTO ddist;
      -- min/max dims
      sql := format('SELECT min(%s), max(%s) FROM %I.%I WHERE %I IS NOT NULL', dims_expr, dims_expr, r.schema, r.table_name, r.column_name);
      EXECUTE sql INTO dmin, dmax;
      -- inconsistent only matters when typmod is fixed or when multiple distinct dims present
      IF r.typmod_dims IS NOT NULL THEN
        sql := format('SELECT count(*) FROM %I.%I WHERE %I IS NOT NULL AND %s <> %s',
                      r.schema, r.table_name, r.column_name, dims_expr, r.typmod_dims::text);
        EXECUTE sql INTO cnt_inconsistent;
      ELSE
        IF ddist IS NOT NULL AND ddist > 1 THEN
          cnt_inconsistent := ddist; -- flag using distinct count (not exact rows)
        END IF;
      END IF;
    END IF;

    -- NaN/Infinity checks via text
    PERFORM 1;
    BEGIN
      sql := format('SELECT count(*) FROM %I.%I WHERE %I::text ~ ''(NaN|Infinity)''', r.schema, r.table_name, r.column_name);
      EXECUTE sql INTO out3; -- reuse var temporarily
      IF out3 > 0 THEN
        INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
        VALUES (r.schema, r.table_name, r.column_name, 'nan_or_infinity_values', out3);
      END IF;
    EXCEPTION WHEN others THEN
      -- ignore casting issues
      NULL;
    END;

    -- Record NULL issue
    IF cnt_null > 0 THEN
      INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
      VALUES (r.schema, r.table_name, r.column_name, 'NULL_vectors', cnt_null);
    END IF;

    -- Record dimension inconsistency
    IF cnt_inconsistent > 0 THEN
      INSERT INTO tmp_vector_issues(schema, table_name, column_name, issue, affected_rows)
      VALUES (r.schema, r.table_name, r.column_name, 'dimension_inconsistent', cnt_inconsistent);
    END IF;

    -- Norm stats and outliers if supported
    an := NULL; sd := NULL; out3 := NULL;
    IF norm_expr IS NOT NULL THEN
      sql := format('SELECT avg(val), stddev_pop(val) FROM (SELECT %s AS val FROM %I.%I WHERE %I IS NOT NULL) t',
                    norm_expr, r.schema, r.table_name, r.column_name);
      EXECUTE sql INTO an, sd;
      IF an IS NOT NULL AND sd IS NOT NULL AND sd > 0 THEN
        sql := format('SELECT count(*) FROM %I.%I WHERE %I IS NOT NULL AND %s > %s + 3*%s',
                      r.schema, r.table_name, r.column_name, norm_expr, an, sd);
        EXECUTE sql INTO out3;
      ELSE
        out3 := 0;
      END IF;
    END IF;

    INSERT INTO tmp_vector_column_stats(schema, table_name, column_name, data_type, typmod_dims,
                                        row_count, null_count, distinct_dims, min_dim, max_dim, avg_norm, stddev_norm, outliers_3sigma)
    VALUES (r.schema, r.table_name, r.column_name, r.data_type, r.typmod_dims,
            COALESCE(rc,0), COALESCE(cnt_null,0), ddist, dmin, dmax, an, sd, COALESCE(out3,0));
  END LOOP;
END $$;

-- Report issues
SELECT * FROM tmp_vector_issues ORDER BY affected_rows DESC NULLS LAST;"}
